/**
 * CollabBranches — Branch management UI for collaborative deck editing.
 *
 * Provides branch creation, switching, merging, and a branch selector dropdown.
 * Branches are stored in D1 via the worker API and tracked in the collab session.
 */

import { h } from '../shared/dom.js';
import { getCollabManager, type CollabEvent, type CollabEventHandler } from './collab-manager.js';
import { getUser } from '../shared/auth.js';

// ───── Types ─────

export interface DeckBranch {
  id: string;
  deckId: string;
  name: string;
  description: string;
  createdBy?: string;
  createdAt: string;
  parentBranchId?: string;
  isDefault: boolean;
}

// ───── State ─────

let branches: DeckBranch[] = [];
let currentBranchId: string | null = null;
let panelVisible = false;
let panelEl: HTMLElement | null = null;
let selectorEl: HTMLElement | null = null;
let deckId: string | null = null;

// ───── Public API ─────

/** Initialize branch system for a deck. */
export function initBranches\(currentDeckId: string\): void {
  deckId = currentDeckId;
  const mgr = getCollabManager\(\);
  mgr.on\('branch-changed', onBranchChanged\);
  mgr.on\('branch-list', onBranchList\);

  // Load branches from API
  loadBranches\(\);
}

/** Get the current branch ID. */
export function getCurrentBranchId\(\): string | null {
  return currentBranchId;
}

/** Get all branches. */
export function getBranches\(\): DeckBranch[] {
  return [...branches];
}

/** Toggle the branch management panel. */
export function toggleBranchPanel\(\): void {
  panelVisible = !panelVisible;
  if \(panelVisible\) {
    showPanel\(\);
  } else {
    hidePanel\(\);
  }
}

/** Is the branch panel currently open? */
export function isBranchPanelOpen\(\): boolean {
  return panelVisible;
}

/** Create the branch selector element for the toolbar. */
export function createBranchSelector\(\): HTMLElement {
  selectorEl = h\('div', { className: 'branch-selector' },
    h\('button', {
      className: 'branch-selector-btn',
      onClick: \(\) => toggleBranchDropdown\(\),
      title: 'Switch branch',
    }, '🌿 main'\),
  \);
  return selectorEl;
}

// ───── API Calls ─────

async function loadBranches\(\): Promise<void> {
  if \(!deckId\) return;
  try {
    const apiOrigin = getApiOrigin\(\);
    const resp = await fetch\(``${apiOrigin}/api/decks/`${deckId}/branches``, {
      credentials: 'include',
    }\);
    if \(!resp.ok\) return;
    const data = await resp.json\(\) as { ok: boolean; data: { branches: DeckBranch[] } };
    if \(data.ok && data.data?.branches\) {
      branches = data.data.branches;
      const defaultBranch = branches.find\(\(b\) => b.isDefault\);
      if \(defaultBranch && !currentBranchId\) {
        currentBranchId = defaultBranch.id;
      }
      updateSelectorLabel\(\);
    }
  } catch {
    // API not available yet or no branches — that's fine
  }
}

async function createBranch\(name: string, description: string\): Promise<DeckBranch | null> {
  if \(!deckId\) return null;
  try {
    const apiOrigin = getApiOrigin\(\);
    const resp = await fetch\(``${apiOrigin}/api/decks/`${deckId}/branches``, {
      method: 'POST',
      credentials: 'include',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify\({ name, description, parentBranchId: currentBranchId }\),
    }\);
    if \(!resp.ok\) return null;
    const data = await resp.json\(\) as { ok: boolean; data: { branch: DeckBranch } };
    if \(data.ok && data.data?.branch\) {
      branches.push\(data.data.branch\);
      updateSelectorLabel\(\);
      renderPanel\(\);
      return data.data.branch;
    }
  } catch {
    // ignore
  }
  return null;
}

async function switchBranch\(branchId: string\): Promise<void> {
  if \(!deckId || branchId === currentBranchId\) return;
  try {
    const apiOrigin = getApiOrigin\(\);
    const resp = await fetch\(``${apiOrigin}/api/decks/`${deckId}/branches/`${branchId}``, {
      credentials: 'include',
    }\);
    if \(!resp.ok\) return;
    const data = await resp.json\(\) as { ok: boolean; data: { branch: DeckBranch; boards: unknown } };
    if \(data.ok\) {
      currentBranchId = branchId;
      updateSelectorLabel\(\);

      // Notify collab manager about branch switch
      getCollabManager\(\).send\({
        type: 'branch-switch',
        branchId,
        branchName: data.data.branch.name,
      } as any\);
    }
  } catch {
    // ignore
  }
}

async function deleteBranch\(branchId: string\): Promise<void> {
  if \(!deckId\) return;
  try {
    const apiOrigin = getApiOrigin\(\);
    const resp = await fetch\(``${apiOrigin}/api/decks/`${deckId}/branches/`${branchId}``, {
      method: 'DELETE',
      credentials: 'include',
    }\);
    if \(resp.ok\) {
      branches = branches.filter\(\(b\) => b.id !== branchId\);
      if \(currentBranchId === branchId\) {
        const defaultBranch = branches.find\(\(b\) => b.isDefault\);
        currentBranchId = defaultBranch?.id || null;
      }
      updateSelectorLabel\(\);
      renderPanel\(\);
    }
  } catch {
    // ignore
  }
}

// ───── Event Handlers ─────

const onBranchChanged: CollabEventHandler = \(event: CollabEvent\) => {
  const data = event.data as { branchId: string; branchName: string };
  if \(data\) {
    currentBranchId = data.branchId;
    updateSelectorLabel\(\);
  }
};

const onBranchList: CollabEventHandler = \(event: CollabEvent\) => {
  const data = event.data as { branches: DeckBranch[] };
  if \(data?.branches\) {
    branches = data.branches;
    updateSelectorLabel\(\);
    renderPanel\(\);
  }
};

// ───── UI Rendering ─────

function updateSelectorLabel\(\): void {
  if \(!selectorEl\) return;
  const btn = selectorEl.querySelector\('.branch-selector-btn'\);
  if \(!btn\) return;
  const current = branches.find\(\(b\) => b.id === currentBranchId\);
  btn.textContent = ``🌿 `${current?.name || 'main'}``;
}

function toggleBranchDropdown\(\): void {
  if \(!selectorEl\) return;
  let dropdown = selectorEl.querySelector\('.branch-dropdown'\) as HTMLElement | null;

  if \(dropdown\) {
    dropdown.remove\(\);
    return;
  }

  dropdown = h\('div', { className: 'branch-dropdown' }\);

  // Branch list
  for \(const branch of branches\) {
    const isCurrent = branch.id === currentBranchId;
    const item = h\('button', {
      className: ``branch-dropdown-item`${isCurrent ? ' active' : ''}``,
      onClick: \(\) => {
        switchBranch\(branch.id\);
        dropdown?.remove\(\);
      },
    },
      h\('span', { className: 'branch-dropdown-name' }, ``${isCurrent ? '● ' : ''}`${branch.name}``\),
      branch.isDefault ? h\('span', { className: 'branch-badge-default' }, 'default'\) : '',
    \);
    dropdown.appendChild\(item\);
  }

  // Create new branch button
  dropdown.appendChild\(h\('div', { className: 'branch-dropdown-divider' }\)\);
  dropdown.appendChild\(h\('button', {
    className: 'branch-dropdown-item branch-dropdown-create',
    onClick: \(\) => {
      dropdown?.remove\(\);
      promptCreateBranch\(\);
    },
  }, '+ New Branch'\)\);

  // Manage branches button
  dropdown.appendChild\(h\('button', {
    className: 'branch-dropdown-item branch-dropdown-manage',
    onClick: \(\) => {
      dropdown?.remove\(\);
      toggleBranchPanel\(\);
    },
  }, '⚙ Manage Branches'\)\);

  selectorEl.appendChild\(dropdown\);

  // Close on click outside
  const closeHandler = \(e: MouseEvent\) => {
    if \(!selectorEl?.contains\(e.target as Node\)\) {
      dropdown?.remove\(\);
      document.removeEventListener\('click', closeHandler\);
    }
  };
  setTimeout\(\(\) => document.addEventListener\('click', closeHandler\), 0\);
}

function promptCreateBranch\(\): void {
  const overlay = h\('div', { className: 'branch-create-overlay' },
    h\('div', { className: 'branch-create-modal' },
      h\('h3', {}, 'Create Branch'\),
      h\('label', {}, 'Name:'\),
      h\('input', {
        type: 'text',
        className: 'branch-create-input',
        placeholder: 'e.g. Budget Version',
        id: '_branchNameInput',
      }\),
      h\('label', {}, 'Description \(optional\):'\),
      h\('input', {
        type: 'text',
        className: 'branch-create-input',
        placeholder: 'e.g. Under `$100 variant',
        id: '_branchDescInput',
      }\),
      h\('div', { className: 'branch-create-actions' },
        h\('button', {
          className: 'branch-create-cancel',
          onClick: \(\) => overlay.remove\(\),
        }, 'Cancel'\),
        h\('button', {
          className: 'branch-create-confirm',
          onClick: async \(\) => {
            const nameEl = document.getElementById\('_branchNameInput'\) as HTMLInputElement;
            const descEl = document.getElementById\('_branchDescInput'\) as HTMLInputElement;
            const name = nameEl?.value?.trim\(\);
            if \(!name\) return;
            await createBranch\(name, descEl?.value?.trim\(\) || ''\);
            overlay.remove\(\);
          },
        }, 'Create'\),
      \),
    \),
  \);
  document.body.appendChild\(overlay\);
  setTimeout\(\(\) => \(document.getElementById\('_branchNameInput'\) as HTMLInputElement\)?.focus\(\), 50\);
}

function showPanel\(\): void {
  if \(panelEl\) {
    panelEl.style.display = 'flex';
    renderPanel\(\);
    return;
  }

  panelEl = h\('div', { className: 'branch-panel' },
    h\('div', { className: 'branch-panel-header' },
      h\('span', { className: 'branch-panel-title' }, '🌿 Branches'\),
      h\('button', {
        className: 'branch-panel-close',
        onClick: \(\) => toggleBranchPanel\(\),
        title: 'Close',
      }, '✕'\),
    \),
    h\('div', { className: 'branch-panel-list', id: '_branchPanelList' }\),
    h\('div', { className: 'branch-panel-actions' },
      h\('button', {
        className: 'branch-panel-create-btn',
        onClick: \(\) => promptCreateBranch\(\),
      }, '+ New Branch'\),
    \),
  \);

  document.body.appendChild\(panelEl\);
  renderPanel\(\);
}

function hidePanel\(\): void {
  if \(panelEl\) {
    panelEl.style.display = 'none';
  }
}

function renderPanel\(\): void {
  const listContainer = document.getElementById\('_branchPanelList'\);
  if \(!listContainer\) return;

  const items = branches.map\(\(branch\) => {
    const isCurrent = branch.id === currentBranchId;
    return h\('div', { className: ``branch-panel-item`${isCurrent ? ' active' : ''}`` },
      h\('div', { className: 'branch-panel-item-info' },
        h\('span', { className: 'branch-panel-item-name' },
          ``${isCurrent ? '● ' : ''}`${branch.name}``,
          branch.isDefault ? h\('span', { className: 'branch-badge-default' }, 'default'\) : '',
        \),
        h\('span', { className: 'branch-panel-item-meta' },
          ``Created `${formatDate\(branch.createdAt\)}``,
        \),
        branch.description
          ? h\('span', { className: 'branch-panel-item-desc' }, branch.description\)
          : '',
      \),
      h\('div', { className: 'branch-panel-item-actions' },
        !isCurrent ? h\('button', {
          className: 'branch-action-btn',
          onClick: \(\) => switchBranch\(branch.id\),
          title: 'Switch to this branch',
        }, 'Switch'\) : '',
        !branch.isDefault ? h\('button', {
          className: 'branch-action-btn branch-action-delete',
          onClick: \(\) => {
            if \(confirm\(``Delete branch "`${branch.name}"?``\)\) {
              deleteBranch\(branch.id\);
            }
          },
          title: 'Delete branch',
        }, '🗑'\) : '',
      \),
    \);
  }\);

  if \(items.length === 0\) {
    listContainer.replaceChildren\(
      h\('div', { className: 'branch-panel-empty' }, 'No branches yet. Create one to try different versions of your deck!'\)
    \);
  } else {
    listContainer.replaceChildren\(...items\);
  }
}

function formatDate\(isoDate: string\): string {
  try {
    return new Date\(isoDate\).toLocaleDateString\(\);
  } catch {
    return isoDate;
  }
}

function getApiOrigin\(\): string {
  if \(window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1'\) {
    return 'http://localhost:8787';
  }
  return 'https://decklens-api.chrisgarkisch.workers.dev';
}
