/**
 * CollabTimeline — Undo/Time-Travel UI for collaborative deck editing.
 *
 * Provides a timeline scrubber showing deck snapshots over time,
 * with the ability to preview and restore any previous state.
 * Integrates with both local undo-stack and server-side snapshots.
 */

import { h } from '../shared/dom.js';
import { getUser } from '../shared/auth.js';

// ───── Types ─────

export interface TimelineSnapshot {
  id: string;
  label: string;
  boardsJson: string;
  userId?: string;
  participantName?: string;
  createdAt: string;
  source: 'local' | 'server' | 'auto';
}

// ───── State ─────

let snapshots: TimelineSnapshot[] = [];
let panelVisible = false;
let panelEl: HTMLElement | null = null;
let listEl: HTMLElement | null = null;
let selectedIndex: number = -1;
let deckId: string | null = null;
let onRestoreCallback: \(\(boardsJson: string\) => void\) | null = null;

const MAX_SNAPSHOTS = 50;

// ───── Public API ─────

/** Initialize the timeline for a specific deck. */
export function initTimeline\(currentDeckId: string, restoreCallback: \(boardsJson: string\) => void\): void {
  deckId = currentDeckId;
  onRestoreCallback = restoreCallback;
  loadServerSnapshots\(\);
}

/** Toggle the timeline panel. */
export function toggleTimelinePanel\(\): void {
  panelVisible = !panelVisible;
  if \(panelVisible\) {
    showPanel\(\);
  } else {
    hidePanel\(\);
  }
}

/** Is the timeline panel open? */
export function isTimelineOpen\(\): boolean {
  return panelVisible;
}

/** Add a snapshot to the timeline \(called from editor on significant changes\). */
export function addSnapshot\(label: string, boardsJson: string, source: 'local' | 'auto' = 'auto'\): void {
  const user = getUser\(\);
  const snap: TimelineSnapshot = {
    id: ``snap_`${Date.now\(\).toString\(36\)}_`${Math.random\(\).toString\(36\).slice\(2, 6\)}``,
    label,
    boardsJson,
    userId: user?.id,
    participantName: user?.displayName || 'You',
    createdAt: new Date\(\).toISOString\(\),
    source,
  };

  snapshots.push\(snap\);
  if \(snapshots.length > MAX_SNAPSHOTS\) {
    snapshots = snapshots.slice\(-MAX_SNAPSHOTS\);
  }

  if \(panelVisible\) renderList\(\);
}

/** Create a named snapshot \(manual save point\). */
export async function createNamedSnapshot\(label: string, boardsJson: string\): Promise<void> {
  addSnapshot\(label, boardsJson, 'local'\);

  // Also persist to server if possible
  if \(deckId\) {
    try {
      const apiOrigin = getApiOrigin\(\);
      await fetch\(``${apiOrigin}/api/decks/`${deckId}/snapshots``, {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify\({ label, boardsJson }\),
      }\);
    } catch {
      // Server save failed, but local snapshot is saved
    }
  }
}

// ───── API Calls ─────

async function loadServerSnapshots\(\): Promise<void> {
  if \(!deckId\) return;
  try {
    const apiOrigin = getApiOrigin\(\);
    const resp = await fetch\(``${apiOrigin}/api/decks/`${deckId}/snapshots``, {
      credentials: 'include',
    }\);
    if \(!resp.ok\) return;
    const data = await resp.json\(\) as { ok: boolean; data: { snapshots: TimelineSnapshot[] } };
    if \(data.ok && data.data?.snapshots\) {
      // Merge server snapshots with local ones
      const serverSnaps = data.data.snapshots.map\(\(s\) => \({ ...s, source: 'server' as const }\)\);
      const merged = [...serverSnaps, ...snapshots.filter\(\(s\) => s.source !== 'server'\)];
      merged.sort\(\(a, b\) => new Date\(a.createdAt\).getTime\(\) - new Date\(b.createdAt\).getTime\(\)\);
      snapshots = merged.slice\(-MAX_SNAPSHOTS\);
      if \(panelVisible\) renderList\(\);
    }
  } catch {
    // API not available
  }
}

async function restoreServerSnapshot\(snapshotId: string\): Promise<void> {
  if \(!deckId\) return;
  try {
    const apiOrigin = getApiOrigin\(\);
    const resp = await fetch\(``${apiOrigin}/api/decks/`${deckId}/snapshots/`${snapshotId}/restore``, {
      method: 'POST',
      credentials: 'include',
    }\);
    if \(resp.ok\) {
      const data = await resp.json\(\) as { ok: boolean; data: { boardsJson: string } };
      if \(data.ok && data.data?.boardsJson\) {
        onRestoreCallback?.\(data.data.boardsJson\);
      }
    }
  } catch {
    // ignore
  }
}

// ───── UI Rendering ─────

function showPanel\(\): void {
  if \(panelEl\) {
    panelEl.style.display = 'flex';
    renderList\(\);
    return;
  }

  panelEl = h\('div', { className: 'timeline-panel' },
    h\('div', { className: 'timeline-panel-header' },
      h\('span', { className: 'timeline-panel-title' }, '⏱ Timeline'\),
      h\('button', {
        className: 'timeline-panel-close',
        onClick: \(\) => toggleTimelinePanel\(\),
        title: 'Close',
      }, '✕'\),
    \),
    h\('div', { className: 'timeline-panel-info' },
      'Click on any snapshot to preview. Click "Restore" to revert to that state.',
    \),
    \(\(\) => { listEl = h\('div', { className: 'timeline-list' }\); return listEl; }\)\(\),
  \);

  document.body.appendChild\(panelEl\);
  renderList\(\);
}

function hidePanel\(\): void {
  if \(panelEl\) {
    panelEl.style.display = 'none';
  }
}

function renderList\(\): void {
  if \(!listEl\) return;

  // Show most recent first
  const reversed = [...snapshots].reverse\(\);

  const items = reversed.map\(\(snap, revIndex\) => {
    const realIndex = snapshots.length - 1 - revIndex;
    const isSelected = realIndex === selectedIndex;
    const timeAgo = formatTimeAgo\(snap.createdAt\);
    const sourceIcon = snap.source === 'server' ? '☁️' : snap.source === 'auto' ? '⚡' : '💾';

    return h\('div', {
      className: ``timeline-entry`${isSelected ? ' selected' : ''}``,
      onClick: \(\) => {
        selectedIndex = realIndex;
        renderList\(\);
      },
    },
      h\('div', { className: 'timeline-entry-marker' },
        h\('div', { className: 'timeline-dot' }\),
        h\('div', { className: 'timeline-line' }\),
      \),
      h\('div', { className: 'timeline-entry-content' },
        h\('div', { className: 'timeline-entry-header' },
          h\('span', { className: 'timeline-entry-label' }, ``${sourceIcon} `${snap.label}``\),
          h\('span', { className: 'timeline-entry-time' }, timeAgo\),
        \),
        snap.participantName
          ? h\('span', { className: 'timeline-entry-author' }, ``by `${snap.participantName}``\)
          : '',
        isSelected
          ? h\('div', { className: 'timeline-entry-actions' },
              h\('button', {
                className: 'timeline-restore-btn',
                onClick: \(e: Event\) => {
                  e.stopPropagation\(\);
                  if \(snap.source === 'server' && snap.id\) {
                    restoreServerSnapshot\(snap.id\);
                  } else {
                    onRestoreCallback?.\(snap.boardsJson\);
                  }
                },
              }, '↩ Restore'\),
            \)
          : '',
      \),
    \);
  }\);

  if \(items.length === 0\) {
    listEl.replaceChildren\(
      h\('div', { className: 'timeline-empty' }, 'No snapshots yet. Snapshots are created automatically as you edit.'\)
    \);
  } else {
    listEl.replaceChildren\(...items\);
  }
}

function formatTimeAgo\(isoDate: string\): string {
  const diff = Date.now\(\) - new Date\(isoDate\).getTime\(\);
  if \(diff < 5000\) return 'just now';
  if \(diff < 60000\) return ``${Math.floor\(diff / 1000\)}s ago``;
  if \(diff < 3600000\) return ``${Math.floor\(diff / 60000\)}m ago``;
  if \(diff < 86400000\) return ``${Math.floor\(diff / 3600000\)}h ago``;
  return new Date\(isoDate\).toLocaleDateString\(\);
}

function getApiOrigin\(\): string {
  if \(window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1'\) {
    return 'http://localhost:8787';
  }
  return 'https://decklens-api.chrisgarkisch.workers.dev';
}
